INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('operation.opensanctions.get-catalog-0f108ac0','List the datasets and collections available as query scopes — the values that go in the path of /search/{dataset}, /match/{dataset} and /reconcile/{dataset}. Returns each dataset''s','List the datasets and collections available as query scopes — the values that go in the path of /search/{dataset}, /match/{dataset} and /reconcile/{dataset}. Returns each dataset''s name, title, summary and description, its publisher and their country, its tags, entity and thing counts, version and last update, and the collections that group it. 478 datasets as of 2026-09-06: collections such as default (everything), sanctions, peps, debarment and crime sit alongside single source lists such as us_ofac_sdn, eu_fsf and gb_hmt_sanctions. Call this first when you need to screen against a specific regime or regulator rather than the whole graph, or to check how fresh a particular list is before relying on it.','source_document','{}','{}','active') ON CONFLICT(slug) DO NOTHING;
