INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('operation.macropulse.get-api-macro-us-revisions-b8e42d20','Has US GDP been revised? BEA revises every estimate (advance, second, third); the Chainlink round history records each revision immutably, timestamped. Returns the ordered revision','Has US GDP been revised? BEA revises every estimate (advance, second, third); the Chainlink round history records each revision immutably, timestamped. Returns the ordered revision trail: every print, when it landed, the change from the previous, and the total revision. Series: gdp/pce/rfs level+change, sofr. Anyone can say GDP grew 2.1%; this says it was first printed at 1.4%, cut to 0.5%, then revised to 2.1% - each step verifiable on-chain.','source_document','{}','{}','active') ON CONFLICT(slug) DO NOTHING;
